#pragma once

/**
 * @file PlayTradeXTypes.h
 * @brief Public data types and callback definitions for the PlayTradeX SDK.
 *
 * Defines wallet-generation types, execution contexts, blockchain network
 * configurations, initialization results, operation responses, prepared
 * transaction information, wallet backup responses, and callback types used
 * by the PlayTradeX public C++ API.
 *
 * PlayTradeX supports multiple configured blockchain networks and
 * transaction execution using either the SDK-managed identity wallet or an
 * application-supplied external wallet.
 *
 * @author Ektishaf Ahwaz
 *
 * @copyright Copyright (c) 2026 PlayTradeX.
 * All rights reserved.
 */

#include <cstdint>
#include <functional>
#include <string>
#include <vector>

namespace PlayTradeX
{
    namespace SDK
    {
        /**
         * @brief Complete EVM wallet generated by the PlayTradeX SDK.
         *
         * Contains the address, public key, and private key produced by a
         * wallet-generation operation.
         *
         * Generated wallets are returned to the application and are not
         * implicitly persisted as the SDK identity wallet. The application is
         * responsible for deciding how generated wallet credentials are used
         * or stored.
         *
         * @warning privateKey contains sensitive wallet credentials. Anyone
         * with access to the private key can control assets associated with
         * the corresponding wallet.
         */
        struct GeneratedWallet
        {
            /**
             * @brief EVM address of the generated wallet.
             */
            std::string address;

            /**
             * @brief Public key of the generated wallet.
             */
            std::string publicKey;

            /**
             * @brief Private key of the generated wallet.
             *
             * @warning Applications must treat this value as sensitive wallet
             * material and protect it appropriately.
             */
            std::string privateKey;
        };

        /**
         * @brief Response returned when wallet generation completes.
         *
         * On success, wallet contains the newly generated wallet information.
         * On failure, errorCode and errorMessage describe the failure.
         */
        struct GenerateWalletResponse
        {
            /**
             * @brief Indicates whether wallet generation succeeded.
             */
            bool success = false;

            /**
             * @brief SDK or wallet-generation error code.
             */
            int errorCode = 0;

            /**
             * @brief Generated wallet information.
             *
             * Contains valid generated wallet information when success is true.
             */
            GeneratedWallet wallet;

            /**
             * @brief Human-readable wallet-generation error message.
             *
             * Empty when no error message is available.
             */
            std::string errorMessage;
        };

        /**
         * @brief Identifies the source of the wallet used for signed operations.
         *
         * WalletSource is used by ExecutionContext to determine which wallet
         * should sign state-changing blockchain transactions.
         */
        enum class WalletSource
        {
            /**
             * @brief Use the PlayTradeX identity wallet managed by the SDK.
             *
             * This is the wallet created or loaded during initialization and
             * used by the PlayTradeX authentication and handshake flow.
             *
             * The SDK resolves the identity wallet internally when a signed
             * operation is prepared.
             */
            Identity,

            /**
             * @brief Use a wallet supplied by the application for this execution.
             *
             * The application's externalPrivateKey from ExecutionContext is
             * used to resolve the transaction signer.
             *
             * PlayTradeX does not persist externally supplied wallets as the
             * SDK identity wallet.
             */
            External
        };

        /**
         * @brief Defines the blockchain network and wallet used by an operation.
         *
         * ExecutionContext allows transaction operations to select both the
         * configured blockchain network and the wallet that will sign the
         * transaction.
         *
         * This separates transaction execution from the SDK's identity wallet,
         * allowing an application to use different wallets with different
         * configured networks without replacing the PlayTradeX identity.
         *
         * @note Operations that require signing use walletSource to resolve the
         * signer. Read-only operations may require only a network identifier
         * and do not necessarily require an ExecutionContext.
         */
        struct ExecutionContext
        {
            /**
             * @brief Identifier of the configured blockchain network on which
             * the operation should execute.
             *
             * The value must identify a network registered with the SDK during
             * initialization.
             */
            std::string networkId;

            /**
             * @brief Determines which wallet should be used when the operation
             * requires transaction signing.
             *
             * Defaults to the SDK-managed identity wallet.
             */
            WalletSource walletSource = WalletSource::Identity;

            /**
             * @brief Private key of an application-managed external wallet.
             *
             * Required only when walletSource is WalletSource::External.
             *
             * PlayTradeX does not persist this key as part of the SDK identity
             * or wallet storage.
             *
             * @warning This value contains sensitive wallet credentials and
             * should only be retained by the application for as long as needed.
             */
            std::string externalPrivateKey;
        };

        /**
         * @brief Result returned when PlayTradeX SDK initialization completes.
         */
        struct InitializeResult
        {
            /**
             * @brief Indicates whether initialization completed successfully.
             */
            bool initialized = false;

            /**
             * @brief Human-readable initialization error message.
             *
             * Empty when initialization succeeds.
             */
            std::string error;

            /**
             * @brief EVM identity wallet address used by the initialized SDK.
             *
             * This represents the SDK-managed identity wallet associated with
             * the PlayTradeX initialization and handshake flow.
             *
             * Empty when initialization fails.
             */
            std::string walletAddress;
        };

        /**
         * @brief Base response shared by PlayTradeX SDK operations.
         *
         * Operation-specific response structures inherit from this type and
         * provide additional result fields.
         */
        struct BaseResponse
        {
            /**
             * @brief Operation success state.
             *
             * Non-zero indicates success. Zero indicates failure.
             */
            int success = 0;

            /**
             * @brief SDK, server, or transport-related error code.
             *
             * Zero normally indicates that no SDK-level error was reported.
             */
            int errorCode = 0;

            /**
             * @brief Raw response body associated with the operation.
             *
             * The exact content depends on the operation and response received
             * by the SDK.
             */
            std::string body;

            /**
             * @brief Human-readable error message.
             *
             * Empty when no error message is available.
             */
            std::string errorMessage;
        };

        /**
         * @brief Response returned when querying the native blockchain balance.
         *
         * The balance represents the native currency of the selected blockchain
         * network for the requested EVM address.
         */
        struct NativeBalanceResponse : public BaseResponse
        {
            /**
             * @brief Native blockchain balance returned by the request.
             */
            std::string balance;
        };

        /**
         * @brief Response returned when converting a smart contract ABI into
         * a human-readable representation.
         */
        struct HumanReadableAbiResponse : public BaseResponse
        {
            /**
             * @brief Human-readable ABI representation.
             */
            std::string abi;
        };

        /**
         * @brief Response returned when a blockchain transaction completes.
         *
         * Used by state-changing operations such as native currency transfers
         * and smart contract write operations.
         */
        struct TransactionResponse : public BaseResponse
        {
            /**
             * @brief Blockchain transaction hash.
             *
             * Empty when the transaction was not successfully submitted or
             * when no transaction hash is available.
             */
            std::string transactionHash;

            /**
             * @brief Transaction receipt returned after transaction processing.
             *
             * The exact representation depends on the response returned by the
             * PlayTradeX service and blockchain network.
             */
            std::string receipt;
        };

        /**
         * @brief Response returned by a read-only smart contract call.
         *
         * Contract reads do not require transaction signing and can be used for
         * view or pure smart contract functions such as ERC-20 balanceOf,
         * allowance, totalSupply, and similar operations.
         */
        struct ContractReadResponse : public BaseResponse
        {
            /**
             * @brief Decoded result returned by the contract call.
             */
            std::string data;
        };

        /**
         * @brief Response returned when exporting a PlayTradeX wallet backup.
         */
        struct WalletExportResponse : public BaseResponse
        {
            /**
             * @brief EVM address of the exported wallet.
             */
            std::string walletAddress;

            /**
             * @brief Path of the generated PlayTradeX wallet backup file.
             *
             * Empty when the export operation fails before a backup file is
             * successfully created.
             */
            std::string filePath;
        };

        /**
         * @brief Response returned when importing a PlayTradeX wallet backup.
         */
        struct WalletImportResponse : public BaseResponse
        {
            /**
             * @brief EVM address restored from the wallet backup.
             *
             * Empty when the import operation fails.
             */
            std::string walletAddress;
        };

        /**
         * @brief Represents a prepared transaction waiting for user consent.
         *
         * The SDK provides this structure through the registered transaction
         * consent callback after resolving the execution network and signer,
         * preparing the transaction, and collecting available blockchain
         * metadata.
         *
         * The transaction has not yet been locally signed or submitted when
         * this structure is presented for consent.
         *
         * Applications should display the relevant transaction information to
         * the user and then call ApproveTransaction() or DenyTransaction()
         * using the supplied transaction ID.
         *
         * The networkId, chainId, and fromAddress fields identify the exact
         * execution context that was resolved when the transaction was
         * prepared.
         *
         * @note A successful simulation does not guarantee successful final
         * execution because blockchain state and network conditions can change.
         */
        struct PreparedTransaction
        {
            /**
             * @brief Unique identifier used to approve or deny the transaction.
             */
            std::string id;

            /**
             * @brief Identifier of the configured blockchain network associated
             * with this transaction.
             */
            std::string networkId;

            /**
             * @brief EVM chain ID of the blockchain network associated with
             * this transaction.
             */
            uint64_t chainId = 0;

            /**
             * @brief Address of the wallet that will sign and submit the
             * transaction.
             *
             * This is the resolved sender address for the transaction and may
             * represent either the SDK-managed identity wallet or an
             * application-supplied external wallet.
             */
            std::string fromAddress;

            /**
             * @brief Blockchain RPC endpoint associated with the transaction.
             *
             * This is the RPC endpoint selected when the transaction was
             * prepared.
             */
            std::string rpc;

            /**
             * @brief Transaction destination or target smart contract address.
             *
             * For contract writes this is the target contract address. For
             * native transfers this identifies the transaction recipient.
             */
            std::string contractAddress;

            /**
             * @brief Smart contract ABI associated with the transaction.
             *
             * May be empty for operations that do not invoke a smart contract
             * function, such as a native currency transfer.
             */
            std::string abi;

            /**
             * @brief Smart contract function being called.
             *
             * Empty for transactions that do not invoke a contract function.
             */
            std::string functionName;

            /**
             * @brief Function parameters in the SDK-supported JSON format.
             *
             * May be empty when the transaction does not contain contract
             * function parameters.
             */
            std::string params;

            /**
             * @brief Native blockchain value attached to the transaction.
             *
             * Use "0" when no native blockchain value is attached.
             */
            std::string value;

            /**
             * @brief Gas limit prepared for the transaction.
             *
             * A value of zero indicates that a usable gas limit was not
             * available during transaction preparation.
             */
            uint64_t gasLimit = 0;

            /**
             * @brief Estimated EIP-1559 base fee per gas.
             *
             * Represented using the SDK's blockchain quantity format.
             */
            std::string baseFeePerGas;

            /**
             * @brief Maximum priority fee per gas prepared for the transaction.
             *
             * Represented using the SDK's blockchain quantity format.
             */
            std::string maxPriorityFeePerGas;

            /**
             * @brief Maximum fee per gas prepared for the transaction.
             *
             * Represented using the SDK's blockchain quantity format.
             */
            std::string maxFeePerGas;

            /**
             * @brief Maximum estimated network fee for the prepared transaction.
             *
             * Calculated from the prepared gas limit and maximum fee per gas.
             * This is an upper-bound estimate and is not necessarily the fee
             * that will actually be paid by the transaction.
             *
             * Stored using the SDK's blockchain quantity representation.
             */
            std::string estimatedMaxNetworkFee;

            /**
             * @brief Indicates whether transaction simulation succeeded.
             *
             * true indicates that the simulation completed successfully.
             * false indicates that simulation failed or could not be completed.
             */
            bool simulationSucceeded = false;

            /**
             * @brief Human-readable simulation failure information.
             *
             * Empty when simulation succeeds or when no additional simulation
             * error information is available.
             */
            std::string simulationError;

            /**
             * @brief Indicates whether the prepared transaction can be submitted.
             *
             * When false, the application should not allow the transaction to
             * be approved for submission.
             */
            bool canSubmit = false;

            /**
             * @brief Human-readable reason the transaction cannot be submitted.
             *
             * Empty when no preparation error was reported.
             */
            std::string preparationError;
        };

        enum class TransactionEventStatus
        {
            Confirmed,
            Reverted
        };

        struct TransactionEvent
        {
            std::string transactionId;
            std::string networkId;

            uint64_t chainId = 0;

            std::string transactionHash;

            TransactionEventStatus status = TransactionEventStatus::Confirmed;

            std::string receipt;
        };

        using TransactionEventListenerId = uint64_t;

        using TransactionEventCallback = std::function<void(const TransactionEvent& event)>;

        /**
         * @brief Configuration for one EVM-compatible blockchain network.
         *
         * Multiple NetworkConfig instances may be supplied during SDK
         * initialization. Operations can subsequently select one of those
         * networks using its id.
         *
         * A network may contain multiple RPC endpoints. The presence of
         * multiple endpoints in the configuration does not itself define a
         * particular endpoint-selection or load-balancing policy.
         */
        struct NetworkConfig
        {
            /**
             * @brief Unique application-defined identifier for this network.
             *
             * Used by ExecutionContext and network-specific SDK operations to
             * select the configured blockchain.
             *
             * Examples: "ethereum", "bsc", "polygon".
             */
            std::string id;

            /**
             * @brief EVM chain ID associated with the network.
             */
            uint64_t chainId = 0;

            /**
             * @brief JSON-RPC endpoints configured for this network.
             *
             * At least one usable endpoint is required by operations that
             * communicate with the blockchain through the network registry.
             */
            std::vector<std::string> rpcEndpoints;
        };

        /**
         * @brief Callback invoked when wallet generation completes.
         *
         * @param response Wallet-generation response containing the generated
         * wallet or failure information.
         *
         * @note The response reference is intended for use during the callback.
         * Applications that need to retain its data should copy the required
         * values.
         */
        using GenerateWalletCallback = std::function<void(const GenerateWalletResponse&)>;

        /**
         * @brief Callback invoked when SDK initialization completes.
         *
         * @param result Initialization result.
         *
         * @note The result reference is intended for use during the callback.
         * Applications that need to retain its data should copy the required
         * values.
         */
        using InitializeCallback = std::function<void(const InitializeResult& result)>;

        /**
         * @brief Callback invoked when a native balance request completes.
         *
         * @param response Native balance response.
         *
         * @note The response reference is intended for use during the callback.
         * Applications that need to retain its data should copy the required
         * values.
         */
        using NativeBalanceCallback = std::function<void(const NativeBalanceResponse& response)>;

        /**
         * @brief Callback invoked when ABI conversion completes.
         *
         * @param response Human-readable ABI conversion response.
         *
         * @note The response reference is intended for use during the callback.
         * Applications that need to retain its data should copy the required
         * values.
         */
        using HumanReadableAbiCallback = std::function<void(const HumanReadableAbiResponse& response)>;

        /**
         * @brief Callback invoked when a blockchain transaction operation
         * completes.
         *
         * Used by native currency transfers and state-changing smart contract
         * operations.
         *
         * @param response Transaction operation response.
         *
         * @note The response reference is intended for use during the callback.
         * Applications that need to retain its data should copy the required
         * values.
         */
        using TransactionCallback = std::function<void(const TransactionResponse& response)>;

        /**
         * @brief Callback invoked when a contract read operation completes.
         *
         * @param response Contract read response.
         *
         * @note The response reference is intended for use during the callback.
         * Applications that need to retain its data should copy the required
         * values.
         */
        using ContractReadCallback = std::function<void(const ContractReadResponse& response)>;

        /**
         * @brief Callback invoked when a prepared transaction requires user
         * consent.
         *
         * The application should present the relevant transaction information
         * to the user and then call ApproveTransaction() or DenyTransaction()
         * using the supplied transaction ID.
         *
         * @param transaction Prepared transaction awaiting user consent.
         *
         * @note The PreparedTransaction reference is intended for use during
         * the callback. Applications that need to retain its data should copy
         * the required values.
         */
        using TransactionConsentCallback = std::function<void(const PreparedTransaction& transaction)>;

        /**
         * @brief Callback invoked when wallet export completes.
         *
         * @param response Wallet export response.
         *
         * @note The response reference is intended for use during the callback.
         * Applications that need to retain its data should copy the required
         * values.
         */
        using WalletExportCallback = std::function<void(const WalletExportResponse& response)>;

        /**
         * @brief Callback invoked when wallet import completes.
         *
         * @param response Wallet import response.
         *
         * @note The response reference is intended for use during the callback.
         * Applications that need to retain its data should copy the required
         * values.
         */
        using WalletImportCallback = std::function<void(const WalletImportResponse& response)>;

    } // namespace SDK
} // namespace PlayTradeX